function Recolor($inPath,$outPath,[double]$targetHue){ $b=New-Object Drawing.Bitmap $inPath; $o=New-Object Drawing.Bitmap $b.Width,$b.Height; for($y=0;$y -lt $b.Height;$y++){ for($x=0;$x -lt $b.Width;$x++){ $p=$b.GetPixel($x,$y); $h=$p.GetHue(); $s=$p.GetSaturation(); $l=$p.GetBrightness(); if($s -gt 0.25 -and $h -gt 60 -and $h -lt 160){ $h=$targetHue + ($h-82)*0.3; $c=$s*(1-[Math]::Abs(2*$l-1)); $hp=$h/60; $xx=$c*(1-[Math]::Abs(($hp % 2)-1)); $r1=0;$g1=0;$b1=0; if($hp -lt 1){$r1=$c;$g1=$xx}elseif($hp -lt 2){$r1=$xx;$g1=$c}else{$g1=$c;$b1=$xx}; $m=$l-$c/2; $o.SetPixel($x,$y,[Drawing.Color]::FromArgb($p.A,[int][Math]::Min(255,($r1+$m)*255),[int][Math]::Min(255,($g1+$m)*255),[int][Math]::Max(0,[Math]::Min(255,($b1+$m)*255)))) } else { $o.SetPixel($x,$y,$p) } } }; $o.Save($outPath,[Drawing.Imaging.ImageFormat]::Png); $b.Dispose(); $o.Dispose() }
